// VCF Ports & Protocols — hand-maintained metadata around the generated PORTS_DATA
// (core/ports.js, regenerated by tools/refresh_ports.mjs): VCF version buckets,
// component → category grouping, "only components in my plan" predicates and the
// role label → form field map used to show the user's own FQDNs/IPs.

// VCF version buckets a PORTS_DATA row can belong to (row.vcfVersions).
export const PORTS_VCF_VERSIONS = ['9.0', '9.1', '9.1.1']

// Default bucket for a plan: form.vcfVersion '9.1.1.0' → '9.1.1', '9.1.0.0' → '9.1', '9.0.x' → '9.0'.
export function portsVersionForPlan(vcfVersion) {
  const v = String(vcfVersion || '')
  if (v.startsWith('9.0')) return '9.0'
  if (v.startsWith('9.1.0')) return '9.1'
  return '9.1.1'
}

// ============================================================
// PORTS & PROTOCOLS — COMPONENT → CATEGORY GROUPING
// ============================================================
export const PORTS_CATEGORY_MAP = {
  'SDDC Manager':'Core Infrastructure', 'vCenter':'Core Infrastructure', 'ESX':'Core Infrastructure',
  'vSAN':'Core Infrastructure', 'NSX':'Core Infrastructure', 'Avi Load Balancer':'Core Infrastructure',
  'VCF Operations':'Fleet Management & Operations', 'VCF Operations for Networks':'Fleet Management & Operations',
  'VCF Operations HCX':'Fleet Management & Operations', 'Log Management':'Fleet Management & Operations',
  'VCF Management Services':'Fleet Management & Operations', 'VCF Operations Fleet Manager':'Fleet Management & Operations',
  'VCF Operations orchestrator':'Automation & Security', 'Identity Broker':'Automation & Security',
  'VCF Automation':'Automation & Security', 'DSM Data Services':'Automation & Security', 'VMware vDefend':'Automation & Security',
  'Protection and Recovery':'Recovery & Disaster Recovery', 'Protection and Recovery Service for VCF Automation':'Recovery & Disaster Recovery',
  'vSphere Replication':'Recovery & Disaster Recovery', 'VMware Live Recovery cloud':'Recovery & Disaster Recovery',
  'VMware Private AI Services':'Private AI',
}
export const PORTS_CATEGORY_ORDER = ['Core Infrastructure','Fleet Management & Operations','Automation & Security','Recovery & Disaster Recovery','Private AI']

// ============================================================
// PORTS & PROTOCOLS — "ONLY COMPONENTS IN MY PLAN" PREDICATES
// ============================================================
// (form, sizing) → true when the component is part of the plan. Core components
// are always shown; optional ones follow the form toggles (vDefend has no form
// toggle, so it follows the Management Domain Sizing "vDefend SSP" component).
const inc = v => v === 'Include'
const hasAutomation = f => f.vcfOpsAutoMode === 'Deploy VCF Operations and Automation' || f.vcfOpsAutoMode === 'Deploy VCF Automation'
export const PORTS_PLAN_PREDICATES = {
  'ESX': () => true,
  'vCenter': () => true,
  'NSX': () => true,
  'SDDC Manager': () => true,
  'VCF Operations': () => true,
  'VCF Management Services': () => true,
  'VCF Operations Fleet Manager': () => true,
  'vSAN': f => !f.principalStorage || String(f.principalStorage).startsWith('vSAN'),
  'VCF Automation': f => hasAutomation(f),
  'VCF Operations orchestrator': f => hasAutomation(f),
  'Identity Broker': f => inc(f.idBrokerInclude),
  'Log Management': f => inc(f.vcfLogsInclude),
  'VCF Operations for Networks': f => inc(f.vcfNetOpsInclude),
  'VCF Operations HCX': f => inc(f.ccmInclude),
  'Avi Load Balancer': f => inc(f.aviInclude),
  'VMware vDefend': (f, s) => !!(s && s.components && s.components.ssp),
  'DSM Data Services': f => inc(f.supervisorInclude) || inc(f.wldSupervisorInclude),
  'VMware Private AI Services': f => inc(f.aiInclude),
  'vSphere Replication': f => inc(f.drInclude),
  'Protection and Recovery': f => inc(f.drInclude),
  'Protection and Recovery Service for VCF Automation': f => inc(f.drInclude) && hasAutomation(f),
  'VMware Live Recovery cloud': f => inc(f.cbrInclude) || inc(f.rwrOnpremInclude),
}

// Unknown products (added upstream before this map is updated) stay visible.
export function portsProductInPlan(product, form, sizing) {
  const pred = PORTS_PLAN_PREDICATES[product]
  return pred ? !!pred(form || {}, sizing) : true
}

// Endpoint lookup tolerant to case/whitespace drift in upstream role labels.
let _endpointIndex = null
export function portsEndpointSpecs(roleLabel) {
  if (!_endpointIndex) {
    _endpointIndex = new Map(Object.entries(PORTS_ENDPOINT_MAP).map(([k, v]) => [k.trim().toLowerCase(), v]))
  }
  return _endpointIndex.get(String(roleLabel || '').trim().toLowerCase()) || null
}

