// Resolves a PORTS_DATA source/destination role label to the endpoints configured in
// the plan: [{ label, fqdn, ip }]. Spec shapes: {fqdnKey, ipKey}, {hosts}, {rangeStartKey, rangeEndKey}.
export function resolvePortsEndpoint(roleLabel, form) {
  const specs = portsEndpointSpecs(roleLabel)
  if (!specs) return []
  const f = form || {}
  const out = []
  for (const spec of specs) {
    if (spec.showWhen && !spec.showWhen(f)) continue
    if (spec.hosts) {
      for (let i = 1; i <= 16; i++) {
        const fqdn = f[`${spec.hosts}Host${i}Fqdn`]
        const ip   = f[`${spec.hosts}Host${i}Ip`]
        if (!fqdn && !ip) continue
        out.push({ label: `${spec.label} ${i}`, fqdn: fqdn || '', ip: ip || '' })
      }
    } else if (spec.rangeStartKey) {
      const a = f[spec.rangeStartKey] || '', b = f[spec.rangeEndKey] || ''
      if (!a && !b) continue
      out.push({ label: spec.label, fqdn: '', ip: a && b ? `${a} – ${b}` : (a || b) })
    } else {
      const fqdn = spec.fqdnKey ? (f[spec.fqdnKey] || '') : ''
      const ip   = spec.ipKey   ? (f[spec.ipKey]   || '') : ''
      if (!fqdn && !ip) continue
      out.push({ label: spec.label, fqdn, ip })
    }
  }
  return out
}
